# Generated by build.py from recipe.yml for recipe mqtt-keep-readings-across-restarts. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'state' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'state/readme.txt'), "the server's data directory`n")
[IO.File]::WriteAllText((Join-Path $PWD 'wait.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh wait.sh <mqtt port> <topic> <expected reading>`nport=`$1`ntopic=`$2`nexpected=`$3`ntry=0`nwhile [ `"`$try`" -lt 20 ]; do`n  # The broker sends the topic's length in two bytes, the topic, then the reading: keep what follows.`n  kept=`$(curl -s `"mqtt://127.0.0.1:`$port/`$topic`" | tail -c +`$(( `${#topic} + 3 )))`n  if [ `"`$kept`" = `"`$expected`" ]; then`n    echo `"kept: `$topic is `$kept`"`n    exit 0`n  fi`n  try=`$(( try + 1 ))`n  sleep 0.5`ndone`necho `"not kept: `$topic`"`nexit 1`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--directory', 'state', '--topic', '"sensors/#;retain"', 'mqtt://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS -d 21.5 mqtt://127.0.0.1:8080/sensors/kitchen/temp --next -sS -d 19.0 mqtt://127.0.0.1:8080/sensors/hall/temp --next -sS -d 22.0 mqtt://127.0.0.1:8080/lab/kitchen/temp --next -sS -d 21.5 mqtt://127.0.0.1:8081/sensors/kitchen/temp
sh wait.sh 8080 sensors/kitchen/temp 21.5
sh wait.sh 8080 sensors/hall/temp 19.0
sh wait.sh 8081 sensors/kitchen/temp 21.5
try { curl.exe -s mqtt://127.0.0.1:8080/sensors/kitchen/temp } finally { Stop-Process $server0 }
